-- CBHPM 2022 - versao agosto/2023. Extraido do PDF fornecido pelo usuario.
-- IMPORTANTE: porte e UCO sao dados classificatorios/referenciais.
-- Nao substitua a precificacao existente do sistema.

create table if not exists public.cbhpm_codigos (
  codigo text primary key,
  codigo_numerico text not null unique,
  descricao text not null,
  tipo_registro text not null,
  selecionavel boolean not null default false,
  capitulo text,
  grupo text,
  grupo_codigo text,
  subgrupo text,
  subgrupo_codigo text,
  porte_medico text,
  custo_operacional_uco_raw text,
  custo_operacional_uco numeric,
  numero_auxiliares smallint,
  porte_anestesico smallint,
  filme_documentacao text,
  ur text,
  codigo_anestesico_correspondente text,
  porte_anestesico_correspondente smallint,
  regra_anestesia text,
  pagina integer,
  versao_fonte text not null default 'CBHPM 2022 - agosto/2023',
  updated_at timestamptz not null default now()
);

create index if not exists idx_cbhpm_codigos_descricao_lower on public.cbhpm_codigos (lower(descricao));
create index if not exists idx_cbhpm_codigos_codigo_numerico on public.cbhpm_codigos (codigo_numerico);
create index if not exists idx_cbhpm_codigos_selecionavel on public.cbhpm_codigos (selecionavel, tipo_registro);

-- Autocomplete oficial: WHERE selecionavel = true AND tipo_registro = 'PROCEDIMENTO'

on conflict (codigo) do update set
  codigo_numerico=excluded.codigo_numerico, descricao=excluded.descricao, tipo_registro=excluded.tipo_registro,
  selecionavel=excluded.selecionavel, capitulo=excluded.capitulo, grupo=excluded.grupo, grupo_codigo=excluded.grupo_codigo,
  subgrupo=excluded.subgrupo, subgrupo_codigo=excluded.subgrupo_codigo, porte_medico=excluded.porte_medico,
  custo_operacional_uco_raw=excluded.custo_operacional_uco_raw, custo_operacional_uco=excluded.custo_operacional_uco,
