  filme_documentacao=excluded.filme_documentacao, ur=excluded.ur,
  codigo_anestesico_correspondente=excluded.codigo_anestesico_correspondente,
  porte_anestesico_correspondente=excluded.porte_anestesico_correspondente, regra_anestesia=excluded.regra_anestesia,
  pagina=excluded.pagina, versao_fonte='CBHPM 2022 - agosto/2023', updated_at=now();

